import * as THREE from 'three';

/** Generated by `npm run convert:props` (Blender scripts in tools/blender/). */
export const FIRE_URL = './models/fire.glb';
export const OBSTACLES_URL = './models/obstacles.glb';

/** Real-world obstacle model for one kind: a shaded body and a part drawn in its action colour. */
export interface ObstacleModel {
  body: THREE.BufferGeometry;
  glow: THREE.BufferGeometry;
}

/**
 * The obstacle models (laser gate, pipes, AC units), each normalised into its collision box.
 * Null (keep the plain boxes) on failure.
 */
export async function loadObstacleModels(
  url = OBSTACLES_URL,
): Promise<Map<string, ObstacleModel> | null> {
  try {
    const { GLTFLoader } = await import('three/examples/jsm/loaders/GLTFLoader.js');
    const gltf = await new GLTFLoader().loadAsync(url);
    const parts = new Map<string, THREE.BufferGeometry>();
    gltf.scene.traverse((o) => {
      const m = o as THREE.Mesh;
      if (m.isMesh) parts.set(m.name, m.geometry);
    });
    const models = new Map<string, ObstacleModel>();
    for (const kind of ['low', 'high', 'mid', 'vault']) {
      const body = parts.get(`${kind}_body`);
      const glow = parts.get(`${kind}_glow`);
      if (body && glow) models.set(kind, { body, glow });
    }
    return models.size ? models : null;
  } catch (e) {
    console.warn('[shadow-shift] obstacle models unavailable, using plain boxes', e);
    return null;
  }
}

/** Flame colours from base to tip (additive, so they glow). */
const FIRE_BASE = new THREE.Color(0xff3d1f);
const FIRE_TIP = new THREE.Color(0xffd27a);

/**
 * The fire model's geometry. Its fire colours are baked into vertex colours (by Blender, see
 * tools/blender/fire.py) so a single instanced, unlit material can draw every flame; a model
 * without them gets a plain base-to-tip gradient. Null (keep the fallback) on failure.
 */
export async function loadFireGeometry(url = FIRE_URL): Promise<THREE.BufferGeometry | null> {
  try {
    const { GLTFLoader } = await import('three/examples/jsm/loaders/GLTFLoader.js');
    const gltf = await new GLTFLoader().loadAsync(url);
    let geo: THREE.BufferGeometry | null = null;
    gltf.scene.traverse((o) => {
      const m = o as THREE.Mesh;
      if (m.isMesh && !geo) geo = m.geometry;
    });
    if (!geo) return null;
    return (geo as THREE.BufferGeometry).getAttribute('color') ? geo : withFireColors(geo);
  } catch (e) {
    console.warn('[shadow-shift] fire model unavailable, using the fallback flame', e);
    return null;
  }
}

/** Bake the flame gradient by height (the model is 0..1 m tall). */
export function withFireColors(geo: THREE.BufferGeometry): THREE.BufferGeometry {
  const pos = geo.getAttribute('position');
  const colors = new Float32Array(pos.count * 3);
  const c = new THREE.Color();
  for (let i = 0; i < pos.count; i++) {
    c.copy(FIRE_BASE).lerp(FIRE_TIP, Math.min(1, Math.max(0, pos.getY(i))));
    colors.set([c.r, c.g, c.b], i * 3);
  }
  geo.setAttribute('color', new THREE.BufferAttribute(colors, 3));
  return geo;
}
